def createparser():
    """Create the argument parser for the pysemver command-line interface.

    :return: an argparse.ArgumentParser instance
    :rtype: argparse.ArgumentParser
    """
    import argparse

    parser = argparse.ArgumentParser(
        prog='pysemver',
        description='Python Semantic Versioning (semver.org) helper tool'
    )

    subparsers = parser.add_subparsers(dest='command')

    # parse command
    parse_parser = subparsers.add_parser('parse', help='Parse a version string')
    parse_parser.add_argument('version', help='Version string to parse')

    # compare command
    compare_parser = subparsers.add_parser('compare', help='Compare two versions')
    compare_parser.add_argument('ver1', help='First version')
    compare_parser.add_argument('ver2', help='Second version')

    # match command
    match_parser = subparsers.add_parser('match', help='Check if version matches expression')
    match_parser.add_argument('version', help='Version string')
    match_parser.add_argument('expression', help='Match expression (e.g., >=1.0.0)')

    # bump commands
    for cmd in ['bump_major', 'bump_minor', 'bump_patch']:
        sub_parser = subparsers.add_parser(cmd.replace('_', '-'),
                                           help=f'Bump {cmd.replace("_", " ")} part')
        sub_parser.add_argument('version', help='Version string')

    # finalize command
    finalize_parser = subparsers.add_parser('finalize',
                                            help='Remove prerelease and build metadata')
    finalize_parser.add_argument('version', help='Version string to finalize')

    return parser


def process(args):
    """Process command-line arguments and execute the appropriate action.

    :param args: list of command-line arguments (without program name)
    :type args: list
    :return: the result of the operation as a string or int
    :rtype: str|int|None
    """
    parser = createparser()
    parsed_args = parser.parse_args(args)

    if parsed_args.command is None:
        parser.print_help()
        return None

    if parsed_args.command == 'parse':
        return parse(parsed_args.version)

    elif parsed_args.command == 'compare':
        return compare(parsed_args.ver1, parsed_args.ver2)

    elif parsed_args.command == 'match':
        return match(parsed_args.version, parsed_args.expression)

    elif parsed_args.command in ('bump-major', 'bump_major'):
        return bump_major(parsed_args.version)

    elif parsed_args.command in ('bump-minor', 'bump_minor'):
        return bump_minor(parsed_args.version)

    elif parsed_args.command in ('bump-patch', 'bump_patch'):
        return bump_patch(parsed_args.version)

    elif parsed_args.command == 'finalize':
        return finalize_version(parsed_args.version)

    else:
        parser.print_help()
        return None


def main():
    """Entry point for the pysemver command-line interface."""
    import sys
    result = process(sys.argv[1:])
    if result is not None:
        print(result)


